from datetime import datetime, timedelta, date
import math

def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    """
    Expand a recurrence rule into UTC occurrences that fall inside the
    window [window_start, window_end) (window_end exclusive).
    All inputs are assumed to be valid ISO‑8601 strings in the specified format.
    """

    # ---------- Helper functions ----------
    def parse_local(dt_str: str) -> datetime:
        """Parse a local date‑time string 'YYYY-MM-DDTHH:MM'."""
        return datetime.strptime(dt_str, "%Y-%m-%dT%H:%M")

    def parse_utc(dt_str: str) -> datetime:
        """Parse a UTC date‑time string 'YYYY-MM-DDTHH:MMZ'."""
        return datetime.strptime(dt_str, "%Y-%m-%dT%H:%MZ")

    def last_day_of_month(year: int, month: int) -> int:
        """Return the last day number of a month."""
        if month == 12:
            return 31
        return (date(year, month + 1, 1) - timedelta(days=1)).day

    # nth weekday of month
    def nth_weekday_of_month(year: int, month: int, n: int, weekday: int):
        """Return a date or None if the nth weekday does not exist."""
        if n > 0:
            first_day = date(year, month, 1)
            offset = (weekday - first_day.weekday()) % 7
            day = 1 + offset + (n - 1) * 7
            if day > last_day_of_month(year, month):
                return None
            return date(year, month, day)
        else:  # n negative
            last_day = date(year, month, last_day_of_month(year, month))
            offset = (last_day.weekday() - weekday) % 7
            day = last_day.day - offset + (n + 1) * 7
            if day < 1:
                return None
            return date(year, month, day)

    # ---------- Validate and extract rule components ----------
    freq = rule.get("freq")
    if freq not in ("daily", "weekly", "monthly", "yearly"):
        raise ValueError("Unknown freq")

    interval = rule.get("interval", 1)
    if not isinstance(interval, int) or interval < 1:
        raise ValueError("Invalid interval")

    # conflict checks
    if "count" in rule and "until" in rule:
        raise ValueError("count and until cannot both be present")
    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError("by_month_day and by_nth_weekday cannot both be present")

    # start and offset
    start_local = parse_local(rule["start"])
    offset_minutes = rule.get("utc_offset_minutes")
    if not isinstance(offset_minutes, int) or not -720 <= offset_minutes <= 840:
        raise ValueError("Invalid utc_offset_minutes")
    offset_td = timedelta(minutes=offset_minutes)

    # exclude set
    exclude_set = set()
    for ex in rule.get("exclude", []):
        exclude_set.add(parse_local(ex))

    # until
    until_local = None
    if "until" in rule:
        until_local = parse_local(rule["until"])

    # count
    count_limit = rule.get("count")
    if count_limit is not None:
        if not isinstance(count_limit, int) or count_limit < 1:
            raise ValueError("Invalid count")

    # by_weekday for weekly
    by_weekday_nums = None
    if freq == "weekly":
        if "by_weekday" in rule:
            lst = rule["by_weekday"]
            if not lst or not isinstance(lst, list):
                raise ValueError("by_weekday must be a non‑empty list")
            WEEKDAY_MAP = {"MO":0,"TU":1,"WE":2,"TH":3,"FR":4,"SA":5,"SU":6}
            by_weekday_nums = sorted({WEEKDAY_MAP[w] for w in lst})
            if len(by_weekday_nums) == 0:
                raise ValueError("by_weekday list empty after dedup")
        else:
            by_weekday_nums = [start_local.weekday()]

    # by_month_day / by_nth_weekday for monthly
    by_month_day_list = None
    by_nth_weekday = None
    if freq == "monthly":
        if "by_month_day" in rule:
            lst = rule["by_month_day"]
            if not lst or not isinstance(lst, list):
                raise ValueError("by_month_day must be a non‑empty list")
            by_month_day_list = sorted({int(d) for d in lst})
            for d in by_month_day_list:
                if not (-31 <= d <= 31) or d == 0:
                    raise ValueError("by_month_day values must be 1..31 or -1..-31")
        elif "by_nth_weekday" in rule:
            arr = rule["by_nth_weekday"]
            if not isinstance(arr, list) or len(arr) != 2:
                raise ValueError("by_nth_weekday must be [n, weekday]")
            n, weekday_str = arr
            if not isinstance(n, int) or not (-5 <= n <= 5) or n == 0:
                raise ValueError("nth weekday n must be 1..5 or -1..-5")
            WEEKDAY_MAP = {"MO":0,"TU":1,"WE":2,"TH":3,"FR":4,"SA":5,"SU":6}
            if weekday_str not in WEEKDAY_MAP:
                raise ValueError("Invalid weekday string in by_nth_weekday")
            by_nth_weekday = (n, WEEKDAY_MAP[weekday_str])
        else:
            by_month_day_list = [start_local.day]  # default day of month

    # yearly month/day
    if freq == "yearly":
        month = start_local.month
        day = start_local.day

    # ---------- Parse window ----------
    window_start_utc = parse_utc(window_start)
    window_end_utc = parse_utc(window_end)
    if window_start_utc > window_end_utc:
        raise ValueError("window_start > window_end")

    window_start_local = window_start_utc + offset_td
    window_end_local = window_end_utc + offset_td

    # If the rule's start is after the window end, no occurrences
    if start_local > window_end_local:
        return []

    # ---------- Occurrence generation ----------
    result = []
    total_generated = 0  # counts potential occurrences, including excluded ones

    def add_occurrence(local_dt: datetime) -> bool:
        """Add an occurrence if it passes count/until/exclude limits.
        Return False if we should stop generating more occurrences."""
        nonlocal total_generated
        if count_limit is not None and total_generated >= count_limit:
            return False
        if until_local is not None and local_dt > until_local:
            return False
        total_generated += 1
        if local_dt not in exclude_set:
            utc_dt = local_dt - offset_td
            result.append(utc_dt.strftime("%Y-%m-%dT%H:%MZ"))
        return True

    # ---------- Daily ----------
    if freq == "daily":
        step_days = interval
        # Compute first candidate after or equal to window_start_local
        delta = window_start_local - start_local
        if delta.total_seconds() <= 0:
            candidate_dt = start_local
        else:
            k = math.ceil(delta.total_seconds() / (step_days * 86400))
            candidate_dt = start_local + timedelta(days=k * step_days)

        while True:
            if candidate_dt > window_end_local:
                break
            if not add_occurrence(candidate_dt):
                break
            candidate_dt += timedelta(days=step_days)

    # ---------- Weekly ----------
    elif freq == "weekly":
        week0_monday = start_local.date() - timedelta(days=start_local.weekday())
        # Compute starting week index
        week_diff = (window_start_local.date() - week0_monday).days // 7
        k_start = max(0, week_diff // interval)
        k = k_start
        while True:
            week_start_date = week0_monday + timedelta(weeks=k * interval)
            if week_start_date > window_end_local.date():
                break
            for wd in by_weekday_nums:
                occ_date = week_start_date + timedelta(days=wd)
                occ_dt = datetime.combine(occ_date, start_local.time())
                if k == 0 and occ_dt < start_local:
                    continue
                if occ_dt > window_end_local:
                    break  # no need to check later weekdays in this week
                if occ_dt < window_start_local:
                    continue
                if not add_occurrence(occ_dt):
                    return result
            k += 1

    # ---------- Monthly ----------
    elif freq == "monthly":
        # months since start month
        months_since_start = (window_start_local.year - start_local.year) * 12 + \
                             (window_start_local.month - start_local.month)
        if months_since_start < 0:
            m_start = 0
        else:
            m_start = ((months_since_start + interval - 1) // interval) * interval
        m = m_start
        while True:
            year = start_local.year + (start_local.month - 1 + m) // 12
            month = (start_local.month - 1 + m) % 12 + 1
            month_start_date = date(year, month, 1)
            if month_start_date > window_end_local.date():
                break
            # Determine candidate days
            days = []
            if by_month_day_list is not None:
                for d in by_month_day_list:
                    if d > 0:
                        if d > last_day_of_month(year, month):
                            continue
                        days.append(d)
                    else:  # negative
                        last_day = last_day_of_month(year, month)
                        dcalc = last_day + d + 1
                        if dcalc < 1:
                            continue
                        days.append(dcalc)
                days = sorted(set(days))
            else:  # by_nth_weekday
                n, wd = by_nth_weekday
                dt = nth_weekday_of_month(year, month, n, wd)
                if dt is not None:
                    days.append(dt.day)
                # else skip this month
            if not days:
                m += interval
                continue
            for d in days:
                occ_dt = datetime(year, month, d, start_local.hour, start_local.minute)
                if m == 0 and occ_dt < start_local:
                    continue
                if occ_dt < window_start_local:
                    continue
                if occ_dt > window_end_local:
                    break
                if not add_occurrence(occ_dt):
                    return result
            m += interval

    # ---------- Yearly ----------
    elif freq == "yearly":
        years_since_start = window_start_local.year - start_local.year
        if years_since_start < 0:
            y_start = 0
        else:
            y_start = ((years_since_start + interval - 1) // interval) * interval
        y = y_start
        while True:
            year = start_local.year + y
            # Skip if month/day invalid (e.g., Feb 29 on non‑leap year)
            try:
                occ_dt = datetime(year, month, day, start_local.hour, start_local.minute)
            except ValueError:
                y += interval
                continue
            if occ_dt > window_end_local:
                break
            if y == 0 and occ_dt < start_local:
                y += interval
                continue
            if occ_dt < window_start_local:
                y += interval
                continue
            if not add_occurrence(occ_dt):
                return result
            y += interval

    return result
